import type { DialogueBeat, MemoryRelationType } from './conversationTypes';
import type { WordCategory } from '../conversationTypes';

export type DerivedWordClassification =
  | { mode: 'fixed'; category: WordCategory; subcategory: string }
  | { mode: 'subcategory'; category: WordCategory }
  | { mode: 'full' };

export type PersonDerivedConversation = {
  id: string;
  parentSubcategory: string;
  title: string;
  opening: DialogueBeat[];
  afterAnswer: DialogueBeat[];
  classification: DerivedWordClassification;
  /** 回答が未来の希望など、通常の関連以外の意味を持つ場合に指定する。 */
  relationType?: MemoryRelationType;
  /** 派生関係の方向など、関連語に添えて保持する補足。 */
  relationQualifier?: string;
  closing: DialogueBeat[];
};

export type PersonDeepDiveConversation = {
  id: string;
  parentSubcategory: string;
  title: string;
  slot: 'slot1' | 'slot2' | 'slot3' | 'slot4' | 'slot5';
  opening: DialogueBeat[];
  /** ペットの現在・過去属性に応じて切り替える質問本文。 */
  statusOpenings?: Partial<Record<'CURRENT' | 'FORMER' | 'UNKNOWN', DialogueBeat[]>>;
  closing: DialogueBeat[];
};

function say(...texts: string[]): DialogueBeat[] {
  return texts.map((text) => ({ text }));
}

